package com.weather.system.controller;

import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import com.weather.system.entity.*;
import com.weather.system.mapper.*;
import org.springframework.web.bind.annotation.*;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.*;

@RestController
@RequestMapping("/api")
public class CrudController {
  private final DeviceMapper devices; private final StationMapper stations; private final MaintainMapper maintains;
  private final WeatherDataMapper weather; private final NoticeMapper notices; private final OperLogMapper logs;
  private final DeviceAlertMapper alerts; private final MaintainPlanMapper plans;
  public CrudController(DeviceMapper d, StationMapper s, MaintainMapper m, WeatherDataMapper w, NoticeMapper n, OperLogMapper l, DeviceAlertMapper a, MaintainPlanMapper p) { devices=d; stations=s; maintains=m; weather=w; notices=n; logs=l; alerts=a; plans=p; }
  @GetMapping("/devices") public Map<String,Object> devices(@RequestParam(defaultValue="1") long page,@RequestParam(defaultValue="10") long size,String status,String type,String keyword){QueryWrapper<Device> q=new QueryWrapper<>();if(status!=null&&!status.trim().isEmpty())q.eq("status",status);if(type!=null&&!type.trim().isEmpty())q.eq("type",type);if(keyword!=null&&!keyword.trim().isEmpty())q.and(x->x.like("name",keyword).or().like("code",keyword));Page<Device> p=devices.selectPage(new Page<>(page,size),q);Map<String,Object> r=new HashMap<>();r.put("records",p.getRecords());r.put("total",p.getTotal());return r;}
  @GetMapping("/devices/{id}/detail") public Map<String,Object> deviceDetail(@PathVariable Long id){Map<String,Object> r=new HashMap<>();r.put("device",devices.selectById(id));r.put("maintains",maintains.selectList(new QueryWrapper<Maintain>().eq("device_id",id).orderByDesc("report_time")));r.put("weather",weather.selectList(new QueryWrapper<WeatherData>().eq("device_id",id).orderByDesc("collect_time").last("limit 24")));return r;}
  @PostMapping("/devices") public Device addDevice(@RequestBody Device d,HttpServletRequest r){checkWrite(r);if(d.getCode()==null||d.getCode().trim().isEmpty())throw new RuntimeException("设备编号不能为空");if(d.getName()==null||d.getName().trim().isEmpty())throw new RuntimeException("设备名称不能为空");if(devices.selectCount(new QueryWrapper<Device>().eq("code",d.getCode()))>0)throw new RuntimeException("设备编号已存在");devices.insert(d);log(r,"新增设备",d.getCode());return d;} @PutMapping("/devices/{id}") public Device editDevice(@PathVariable Long id,@RequestBody Device d,HttpServletRequest r){checkWrite(r);if(d.getCode()==null||d.getCode().trim().isEmpty())throw new RuntimeException("设备编号不能为空");if(d.getName()==null||d.getName().trim().isEmpty())throw new RuntimeException("设备名称不能为空");if(devices.selectCount(new QueryWrapper<Device>().eq("code",d.getCode()).ne("id",id))>0)throw new RuntimeException("设备编号已存在");d.setId(id);devices.updateById(d);log(r,"编辑设备",String.valueOf(id));return devices.selectById(id);} @DeleteMapping("/devices/{id}") public void deleteDevice(@PathVariable Long id,HttpServletRequest r){checkAdmin(r);devices.deleteById(id);log(r,"删除设备",String.valueOf(id));}
  @GetMapping("/devices/export") public void export(HttpServletResponse response)throws Exception{response.setContentType("text/csv;charset=UTF-8");response.setHeader("Content-Disposition","attachment;filename=devices.csv");StringBuilder b=new StringBuilder("设备编号,设备名称,类型,型号,厂家,状态\n");for(Device d:devices.selectList(null))b.append(d.getCode()).append(',').append(d.getName()).append(',').append(d.getType()).append(',').append(d.getModel()).append(',').append(d.getManufacturer()).append(',').append(d.getStatus()).append('\n');response.getWriter().write("\uFEFF"+b);}
  @GetMapping("/stations") public List<Station> stations(){return stations.selectList(null);} @PostMapping("/stations") public Station addStation(@RequestBody Station s,HttpServletRequest r){checkWrite(r);stations.insert(s);log(r,"新增站点",s.getName());return s;} @PutMapping("/stations/{id}") public Station editStation(@PathVariable Long id,@RequestBody Station s,HttpServletRequest r){checkWrite(r);s.setId(id);stations.updateById(s);log(r,"编辑站点",String.valueOf(id));return s;} @DeleteMapping("/stations/{id}") public void delStation(@PathVariable Long id,HttpServletRequest r){checkAdmin(r);stations.deleteById(id);log(r,"删除站点",String.valueOf(id));}
  @GetMapping("/maintains") public List<Maintain> maintains(){return maintains.selectList(new QueryWrapper<Maintain>().orderByDesc("report_time"));} @PostMapping("/maintains") public Maintain addMaintain(@RequestBody Maintain m,HttpServletRequest r){checkWrite(r);if(m.getReportTime()==null)m.setReportTime(LocalDateTime.now());maintains.insert(m);log(r,"新建维修工单",String.valueOf(m.getDeviceId()));return m;} @PutMapping("/maintains/{id}") public Maintain editMaintain(@PathVariable Long id,@RequestBody Maintain m,HttpServletRequest r){checkWrite(r);m.setId(id);maintains.updateById(m);log(r,"更新维修工单",String.valueOf(id));return m;}
  @GetMapping("/weather") public List<WeatherData> weather(@RequestParam(required=false)Long deviceId){QueryWrapper<WeatherData> q=new QueryWrapper<>();if(deviceId!=null)q.eq("device_id",deviceId);return weather.selectList(q.orderByAsc("collect_time"));} @PostMapping("/weather/simulate") public WeatherData simulate(@RequestBody WeatherData d,HttpServletRequest r){checkWrite(r);if(d.getCollectTime()==null)d.setCollectTime(LocalDateTime.now());weather.insert(d);log(r,"模拟上传气象数据",String.valueOf(d.getDeviceId()));return d;}
  @GetMapping("/notices") public List<Notice> notices(){return notices.selectList(new QueryWrapper<Notice>().orderByDesc("publish_time"));} @PostMapping("/notices") public Notice addNotice(@RequestBody Notice n,HttpServletRequest r){checkWrite(r);n.setPublisher((String)r.getAttribute("username"));n.setPublishTime(LocalDateTime.now());notices.insert(n);log(r,"发布公告",n.getTitle());return n;}
  @GetMapping("/alerts") public List<DeviceAlert> alertList(){refreshAlerts();return alerts.selectList(new QueryWrapper<DeviceAlert>().orderByDesc("created_at"));} @PutMapping("/alerts/{id}/ack") public void ackAlert(@PathVariable Long id,HttpServletRequest r){DeviceAlert a=alerts.selectById(id);if(a!=null){a.setStatus("closed");a.setAcknowledgedBy((String)r.getAttribute("username"));a.setAcknowledgedAt(LocalDateTime.now());alerts.updateById(a);log(r,"处理设备告警",String.valueOf(id));}}
  @GetMapping("/plans") public List<MaintainPlan> plans(){return plans.selectList(new QueryWrapper<MaintainPlan>().orderByAsc("next_date"));} @PostMapping("/plans") public MaintainPlan addPlan(@RequestBody MaintainPlan p,HttpServletRequest r){checkWrite(r);if(p.getCreateTime()==null)p.setCreateTime(LocalDateTime.now());if(p.getStatus()==null)p.setStatus("pending");plans.insert(p);log(r,"新增保养计划",p.getTitle());return p;} @PutMapping("/plans/{id}") public MaintainPlan editPlan(@PathVariable Long id,@RequestBody MaintainPlan p,HttpServletRequest r){checkWrite(r);p.setId(id);plans.updateById(p);log(r,"编辑保养计划",String.valueOf(id));return p;} @DeleteMapping("/plans/{id}") public void deletePlan(@PathVariable Long id,HttpServletRequest r){checkAdmin(r);plans.deleteById(id);log(r,"删除保养计划",String.valueOf(id));}
  @GetMapping("/logs") public List<OperLog> logList(@RequestParam(required=false)String operator){QueryWrapper<OperLog> q=new QueryWrapper<>();if(operator!=null&&!operator.trim().isEmpty())q.eq("operator",operator);return logs.selectList(q.orderByDesc("operate_time").last("limit 100"));}
  @GetMapping("/analytics") public Map<String,Object> analytics(){Map<String,Object> r=new HashMap<>();r.put("byStatus",devices.selectMaps(new QueryWrapper<Device>().select("status","count(*) as total").groupBy("status")));r.put("byType",devices.selectMaps(new QueryWrapper<Device>().select("type","count(*) as total").groupBy("type")));r.put("weather",weather.selectList(new QueryWrapper<WeatherData>().orderByAsc("collect_time").last("limit 48")));r.put("alerts",alerts.selectCount(new QueryWrapper<DeviceAlert>().eq("status","open")));return r;}
  @GetMapping("/dashboard") public Map<String,Object> dashboard(){refreshAlerts();Map<String,Object> m=new HashMap<>();m.put("deviceTotal",devices.selectCount(null));m.put("faultTotal",devices.selectCount(new QueryWrapper<Device>().eq("status","fault")));m.put("maintainTotal",maintains.selectCount(null));m.put("stationTotal",stations.selectCount(null));m.put("alertTotal",alerts.selectCount(new QueryWrapper<DeviceAlert>().eq("status","open")));m.put("planDue",plans.selectCount(new QueryWrapper<MaintainPlan>().eq("status","pending").le("next_date", LocalDate.now().plusDays(7))));m.put("weather",weather.selectList(new QueryWrapper<WeatherData>().orderByDesc("collect_time").last("limit 12")));return m;}
  private void refreshAlerts(){for(Device d:devices.selectList(new QueryWrapper<Device>().eq("status","fault"))){QueryWrapper<DeviceAlert> q=new QueryWrapper<DeviceAlert>().eq("device_id",d.getId()).eq("status","open").eq("type","设备故障");if(alerts.selectCount(q)==0){DeviceAlert a=new DeviceAlert();a.setDeviceId(d.getId());a.setType("设备故障");a.setLevel("high");a.setMessage(d.getName()+"当前状态为故障");a.setStatus("open");a.setCreatedAt(LocalDateTime.now());alerts.insert(a);}}}
  private void checkWrite(HttpServletRequest r){String role=(String)r.getAttribute("role");if(!"admin".equals(role)&&!"maintainer".equals(role))throw new RuntimeException("权限不足");} private void checkAdmin(HttpServletRequest r){if(!"admin".equals(r.getAttribute("role")))throw new RuntimeException("权限不足");} private void log(HttpServletRequest r,String action,String target){OperLog l=new OperLog();l.setOperator((String)r.getAttribute("username"));l.setAction(action);l.setTarget(target);l.setOperateTime(LocalDateTime.now());l.setIp(r.getRemoteAddr());logs.insert(l);}
}
